package com.jian.scrcpy.protocol;import io.netty.buffer.*;import io.netty.channel.embedded.EmbeddedChannel;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ConfigPacketMergerTest{@Test void prependsConfig(){var c=new EmbeddedChannel(new ConfigPacketMerger());c.writeInbound(new MediaMessage.Packet(-1,true,false,Unpooled.wrappedBuffer(new byte[]{1,2})));c.writeInbound(new MediaMessage.Packet(10,false,true,Unpooled.wrappedBuffer(new byte[]{3})));var p=(MediaMessage.Packet)c.readInbound();assertArrayEquals(new byte[]{1,2,3},io.netty.buffer.ByteBufUtil.getBytes(p.data()));p.data().release();c.finishAndReleaseAll();}}